cd /c/Dot; cat > "$TEMP/claude/c--Dot/00000000-0000/scratchpad/p56.cjs" <<'XEOF'
const fs = require('fs');
const p = 'C:/Dot/bridge/config.js';
let s = fs.readFileSync(p, 'utf8');
const crlf = s.includes('\r\n');
s = s.split('\r\n').join('\n');
const rep = (a, b) => { if (!s.includes(a)) throw new Error('missing: ' + a.slice(0, 70)); s = s.replace(a, b); };
rep(`  custom: null,         // your own pal: { name, shape, eyes, top, color, fur }`, `  custom: null,         // your own pal: { name, shape, eyes, top, color, fur }
  storyView: 'simple',  // how requests read by default: 'simple' (one sentence) or 'detailed' (the chapters)`);
rep(`  if (CHARACTERS.includes(input.character)) out.character = input.character;`, `  if (CHARACTERS.includes(input.character)) out.character = input.character;
  if (input.storyView === 'simple' || input.storyView === 'detailed') out.storyView = input.storyView;`);
fs.writeFileSync(p, crlf ? s.split('\n').join('\r\n') : s);
console.log('ok');
XEOF
node "$TEMP/claude/c--Dot/00000000-0000/scratchpad/p56.cjs"; grep -n "case 'config'\|type === 'config'\|'config')\|applyConfig\|function onConfig" bridge/index.html bridge/notch.html bridge/dashboard.html | head

