  fs.writeFileSync(p, crlf ? s.split('\n').join('\r\n') : s);
};
// The pal: your own pick (localStorage) wins; else the setting (config.storyView, chosen at setup).
edit('C:/Dot/bridge/index.html', [
  [`    let recapView = (() => { try { return localStorage.getItem('dotpals.view') === 'detailed' ? 'detailed' : 'simple'; } catch { return 'simple'; } })();`,
   `    const picke
…
;`],
  [`      } else if (type === 'config') {`, `      } else if (type === 'config') {
        if (data.storyView === 'simple' || data.storyView === 'detailed') defaultView = data.storyView;`],
]);
edit('C:/Dot/bridge/dashboard.html', [
  [`    const storyView = () => { try { return localStorage.getItem('dotpals.view') === 'detailed' ? 'detailed' : 'simple'; } catch { return 'simple'; } };`,
   `    const storyView = () => { let v = null; try { v = localStorage.getItem('dotpals.view'); } catch {} return (v ?? config.storyView) === 'detailed' ? 'detailed' : 'simple'; };`],
]);
console.log('ok');
XEOF
node "$TEMP/claude/c--Dot/00000000-0000/scratchpad/p57.cjs"; grep -n "function scheduleRecap\|const scheduleRecap" bridge/index.html | head -2

